// Contract tests against the schemas generated by contract/ (another worker owns the files; they are read only).
// Skipped, with a message, while the files do not exist yet.

import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { describe, it } from 'node:test';
import { fileURLToPath } from 'node:url';
import Ajv from 'ajv';
import addFormats from 'ajv-formats';
import { bootstrap, catchUp, command } from '../src/engine';
import { COMMAND_TYPES } from '../src/engine';
import { H, PLAYER, T0, buildTutorialLine, newFactory } from './helpers';

const contractDir = fileURLToPath(new URL('../../contract/', import.meta.url));
const snapshotSchemaPath = contractDir + 'schema/snapshot.schema.json';
const commandExamplesPath = contractDir + 'examples/commands.json';

const noSchema = existsSync(snapshotSchemaPath) ? false : 'contract/schema/snapshot.schema.json is not generated yet (run contract/generate.sh)';
const noExamples = existsSync(commandExamplesPath) ? false : 'contract/examples/commands.json is not present yet';

function snapshotValidator() {
	const ajv = new Ajv({ allErrors: true, strict: false });
	addFormats(ajv);
	const validate = ajv.compile(JSON.parse(readFileSync(snapshotSchemaPath, 'utf8')));
	return (snapshot: unknown, label: string) => {
		const ok = validate(snapshot);
		assert.ok(ok, `${label}: snapshot does not match GameSnapshot schema\n${ajv.errorsText(validate.errors, { dataVar: 'snapshot' })}`);
	};
}

describe('snapshot matches contract/schema/snapshot.schema.json', { skip: noSchema }, () => {
	it('bootstrap(null) and bootstrap(existing)', async () => {
		const check = snapshotValidator();
		const b = await bootstrap(null, T0, PLAYER);
		check(b.snapshot, 'bootstrap(null)');
		check((await bootstrap(b.state, T0 + 20 * 60_000)).snapshot, 'bootstrap(existing)');
	});

	it('command: accepted, rejected, with a built factory and a loading order', async () => {
		const check = snapshotValidator();
		const built = await buildTutorialLine(await newFactory(), T0);
		const ok = await command(built.state, built.now + 1000, { type: 'renameFactory', name: 'Квас-1' });
		check(ok.snapshot, 'command ok');
		const rejected = await command(built.state, built.now + 1000, { type: 'renameFactory', name: 'x' });
		check(rejected.snapshot, 'command rejected');
		const tick = await command(built.state, built.now + 1000, { type: 'tick', from: 0, to: 1, events: [] });
		check(tick.snapshot, 'tick_removed');
		const dock = (built.state as any).sim.layout.buildings.find((b: any) => b.kind === 'dock');
		const order = (built.state as any).sim.orders[0];
		const acc = await command(built.state, built.now + 2000, { type: 'acceptOrder', orderId: order.id, dockId: dock.id });
		assert.equal(acc.result.ok, true);
		check(acc.snapshot, 'acceptOrder');
	});

	it('advance: short, offline report, capped, beyond the cap', async () => {
		const check = snapshotValidator();
		const built = await buildTutorialLine(await newFactory(), T0);
		for (const [dh, cap] of [[0.01, undefined], [3, undefined], [5, 1], [30, undefined]] as const) {
			check((await catchUp(built.state, built.now + dh * H, cap)).snapshot, `advance ${dh}h cap=${cap}`);
		}
	});
});

describe('every contract/examples command is served without crashing', { skip: noExamples }, () => {
	it('all example commands return a well-formed outcome (never an exception)', async () => {
		const examples = JSON.parse(readFileSync(commandExamplesPath, 'utf8')) as Record<string, { type: string }[]>;
		const built = await buildTutorialLine(await newFactory(), T0);
		let n = 0;
		for (const [type, list] of Object.entries(examples)) {
			assert.ok(COMMAND_TYPES.has(type), `sim knows command type ${type}`);
			for (const cmd of list) {
				const r = await command(built.state, built.now + 1000, cmd as never);
				assert.equal(typeof r.result.ok, 'boolean', type);
				assert.ok(r.snapshot, type);
				n++;
			}
		}
		assert.ok(n > 20);
	});
});
